/* SCRIPT QUE AGREGA 2 DECIMALES AL CAMPO TIPO CAMBIO DE LA DJ */


/* CAMBIA EL TIPO DE DATO A DECIMAL PARA EL CAMPO TIPO CAMBIO */
UPDATE BSCL."BSCL.Normativa.BD::DOC.Campo" SET "TipoDato" = 'DECIMAL'
WHERE "Esquema" = 'DJ1870' 
AND "Nombre" = 'TipoCambio';

/* AGREGA 2 DECIMALES A CAMPO TIPO CAMBIO DECIMAL*/
UPDATE BSCL."BSCL.Normativa.BD::DOC.Campo" SET "CantidadDecimales" = 2 
WHERE "Esquema" = 'DJ1870' 
AND "Nombre" = 'TipoCambio';

/* Ingreso GrabarMasivo */

INSERT INTO BSCL."BSCL.Plataforma.BD::PLA.Servicio"
("IdServicio", "RutaServicio", "UsoServicio", "TipoServicio", "Descripcion", "TablasTempIN", "TablasTempOUT", "RegistraUso")
SELECT 4290715, 'BSCL.Normativa.BD.Servicios::TRI.DJ1870.GrabarMasivo', 1, 'P', '', '', '', 'S'
FROM DUMMY 
WHERE NOT EXISTS (SELECT 1 FROM BSCL."BSCL.Plataforma.BD::PLA.Servicio" WHERE "IdServicio"=4290715);


/* REINICIA TODOS LOS CAMPOS EN MODO MASIVO = NO */
UPDATE BSCL."BSCL.Normativa.BD::DOC.Campo" SET "ModoMasivo" = 'N'
WHERE "Esquema" = 'DJ1870';

